package io.github.jesterportfolio.hearth.survival.rpg;

import java.nio.file.*;import java.nio.channels.FileChannel;import java.util.*;import java.util.concurrent.*;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.*;import org.bukkit.inventory.ItemStack;import org.bukkit.persistence.PersistentDataType;import org.bukkit.plugin.java.JavaPlugin;
import dev.aurelium.auraskills.api.*;import dev.aurelium.auraskills.api.registry.*;import dev.aurelium.auraskills.api.skill.*;import dev.aurelium.auraskills.api.stat.*;import dev.aurelium.auraskills.api.ability.*;import dev.aurelium.auraskills.api.mana.*;import dev.aurelium.auraskills.api.event.skill.SkillsLoadEvent;import dev.aurelium.auraskills.api.util.AuraSkillsModifier.Operation;
import io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy;

/** 공개 API 콘텐츠·장비 bridge. 원본 플러그인을 fork/reflect하지 않는다. */
public final class RpgAura implements Listener,AutoCloseable {
    public record Custom(CustomSkill skill,CustomAbility passive,CustomManaAbility active,String stat,String effect,double activeValue,int seconds){}
    public record Gear(String id,String stat,double upgrade,String enchant,double enchantValue,double cap,Set<Integer> slots,Set<String> materials){}
    public final JavaPlugin plugin;public final Properties content;public final RpgPolicy policy;public final AuraSkillsApi api;
    public final Map<String,Custom> custom=new LinkedHashMap<>();public final List<Gear> gear=new ArrayList<>();
    private final CompletableFuture<Void> initial=new CompletableFuture<>();private long generation;private boolean closed;
    private final Map<UUID,Map<String,Double>> applied=new HashMap<>();
    public final io.github.jesterportfolio.hearth.survival.platform.StatLedger statLedger=new io.github.jesterportfolio.hearth.survival.platform.StatLedger();
    private final Map<UUID,Map<String,Map<String,io.github.jesterportfolio.hearth.survival.platform.StatLedger.Contribution>>> sources=new HashMap<>();
    private final Map<UUID,Map<String,Double>> rendered=new HashMap<>();
    public void statPolicy(String mode,double cap){statLedger.policy(mode,cap);rendered.clear();}
    public void source(UUID player,String namespace,String id,String stat,double amount){var map=sources.computeIfAbsent(player,k->new HashMap<>()).computeIfAbsent(namespace,k->new HashMap<>());map.put(id,new io.github.jesterportfolio.hearth.survival.platform.StatLedger.Contribution(stat,amount));replaceSources(player,namespace,map);}
    public void removeSource(UUID player,String namespace,String id){var map=sources.getOrDefault(player,Map.of()).get(namespace);if(map!=null){map.remove(id);replaceSources(player,namespace,map);}}
    public void replaceSources(UUID player,String namespace,Map<String,io.github.jesterportfolio.hearth.survival.platform.StatLedger.Contribution> values){if(!Bukkit.isPrimaryThread())throw new IllegalStateException("STAT_MAIN_THREAD");var user=api.getUser(player);if(!user.isLoaded())return;var next=statLedger.replace(player,namespace,values).totals();if(next.equals(rendered.get(player)))return;for(String id:new HashSet<>(user.getStatModifiers().keySet()))if(id.startsWith("hearth:platform/")||id.startsWith("hearth:gear/")||id.startsWith("hearth:passive/")||id.startsWith("hearth:enchant/"))user.removeStatModifier(id);next.forEach((id,value)->{var modifier=new StatModifier("hearth:platform/"+id,stat(id),value,Operation.ADD);modifier.setNonPersistent();user.addStatModifier(modifier);});rendered.put(player,next);}
    public void clearSources(UUID player){sources.remove(player);statLedger.clear(player);var user=api.getUser(player);if(user.isLoaded())for(String id:new HashSet<>(user.getStatModifiers().keySet()))if(id.startsWith("hearth:platform/"))user.removeStatModifier(id);rendered.remove(player);applied.remove(player);}
    @EventHandler public void forget(PlayerQuitEvent e){clearSources(e.getPlayer().getUniqueId());}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void died(org.bukkit.event.entity.PlayerDeathEvent e){clearSources(e.getEntity().getUniqueId());}
    public RpgAura(JavaPlugin plugin)throws Exception{
        this.plugin=plugin;var aura=Objects.requireNonNull(Bukkit.getPluginManager().getPlugin("AuraSkills"),"AURASKILLS_REQUIRED");if(!aura.isEnabled()||!aura.getDescription().getVersion().equals("2.4.0"))throw new IllegalStateException("AURASKILLS_VERSION");
        policy=RpgPolicy.parse(read(plugin,"economy-rpg.policy-file","rpg-policy.properties"));content=read(plugin,"economy-rpg.content-file","rpg-content.properties");api=AuraSkillsApi.get();var dir=plugin.getDataFolder().toPath().toAbsolutePath().resolve("rpg-aura-content");Files.createDirectories(dir);if(!dir.equals(dir.toRealPath()))throw new IllegalStateException("RPG_CONTENT_PATH");var registry=api.useRegistry("hearth",dir.toFile());
        for(String id:list("custom-stats")){String prefix="stat."+id+".";var trait=api.getGlobalRegistry().getTrait(NamespacedId.fromString(RpgPolicy.required(content,prefix+"trait")));if(trait==null)throw new IllegalArgumentException("RPG_CUSTOM_TRAIT");registry.registerStat(CustomStat.builder(NamespacedId.of("hearth",id)).displayName(RpgPolicy.required(content,prefix+"name")).description("Hearth").color("<white>").symbol("+").trait(trait,number(prefix+"coefficient",-10000,10000)).build());}
        var skillConfig=new org.bukkit.configuration.file.YamlConfiguration();
        for(String id:list("custom-skills")){String prefix="skill."+id+".";var passive=CustomAbility.builder(NamespacedId.of("hearth",id+"_passive")).displayName(RpgPolicy.required(content,prefix+"name")).description("Hearth passive").baseValue(number(prefix+"passive-base",-10000,10000)).valuePerLevel(number(prefix+"passive-per-level",-10000,10000)).unlock(1).levelUp(1).maxLevel(100).build();var active=CustomManaAbility.builder(NamespacedId.of("hearth",id+"_active")).displayName(RpgPolicy.required(content,prefix+"name")).description("Hearth active").baseValue(number(prefix+"active-value",0,10000)).baseManaCost(number(prefix+"active-mana",0,100000)).baseCooldown(number(prefix+"active-cooldown",1,3600)).unlock(1).levelUp(1).maxLevel(100).build();var skill=CustomSkill.builder(NamespacedId.of("hearth",id)).displayName(RpgPolicy.required(content,prefix+"name")).description("Hearth custom skill").ability(passive).manaAbility(active).build();registry.registerAbility(passive);registry.registerManaAbility(active);registry.registerSkill(skill);String effect=RpgPolicy.required(content,prefix+"active-effect");if(!Set.of("HEAL","SPEED","HASTE","RESISTANCE").contains(effect))throw new IllegalArgumentException("RPG_EFFECT");custom.put(id,new Custom(skill,passive,active,RpgPolicy.required(content,prefix+"passive-stat"),effect,number(prefix+"active-value",0,10000),(int)number(prefix+"active-seconds",1,600)));skillConfig.set("skills.hearth/"+id+".mana_ability",active.getId().toString());}
        skillConfig.save(dir.resolve("skills.yml").toFile());
        for(String id:list("gear-stats")){String prefix="gear."+id+".";gear.add(new Gear(id,RpgPolicy.required(content,prefix+"stat"),number(prefix+"upgrade-per-level",-10000,10000),RpgPolicy.required(content,prefix+"enchant-key"),number(prefix+"enchant-per-level",-10000,10000),number(prefix+"cap",0,1_000_000),Arrays.stream(RpgPolicy.required(content,prefix+"slots").split(",")).map(String::strip).map(slot->List.of("main_hand","off_hand","head","chest","legs","feet").indexOf(slot)).collect(java.util.stream.Collectors.toUnmodifiableSet()),Set.copyOf(Arrays.stream(RpgPolicy.required(content,prefix+"materials").split(",")).map(String::strip).toList())));}
        Bukkit.getPluginManager().registerEvents(this,plugin);
    }
    public static Properties read(JavaPlugin plugin,String setting,String fallback)throws Exception{String name=plugin.getConfig().getString(setting,fallback);if(name==null||!name.matches("[A-Za-z0-9_-]+\\.properties"))throw new IllegalArgumentException("RPG_CONFIG_PATH");Path file=plugin.getDataFolder().toPath().resolve(name).toAbsolutePath();if(!file.equals(file.toRealPath())||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>131072)throw new IllegalArgumentException("RPG_CONFIG_PATH");var p=new Properties();try(var r=Files.newBufferedReader(file)){p.load(r);}return p;}
    private List<String> list(String key){String raw=RpgPolicy.required(content,key);if(raw.isEmpty())return List.of();var ids=Arrays.stream(raw.split(",")).map(String::strip).toList();if(ids.size()>32||new HashSet<>(ids).size()!=ids.size()||ids.stream().anyMatch(id->!id.matches("[a-z][a-z0-9_]{0,24}")))throw new IllegalArgumentException("RPG_CONTENT_IDS");return ids;}
    private double number(String key,double lo,double hi){double n=Double.parseDouble(RpgPolicy.required(content,key));if(!Double.isFinite(n)||n<lo||n>hi)throw new IllegalArgumentException(key);return n;}
    private void validateContent(){for(var g:gear){stat(g.stat());if(g.slots().contains(-1)||NamespacedKey.fromString(g.enchant())==null||g.materials().stream().anyMatch(id->Material.matchMaterial(id)==null))throw new IllegalArgumentException("RPG_GEAR_PROFILE");}for(var c:custom.values()){stat(c.stat());if(!c.skill().isEnabled()||!c.active().isEnabled())throw new IllegalStateException("RPG_CUSTOM_DISABLED");}if(policy.penaltyEnabled())for(String id:policy.penaltyRule().skills())if(skill(id)==null||!skill(id).isEnabled())throw new IllegalStateException("RPG_PENALTY_SKILL");generation++;applied.clear();rendered.clear();}
    @EventHandler public void loaded(SkillsLoadEvent e){if(closed)return;try{validateContent();initial.complete(null);}catch(Exception error){initial.completeExceptionally(error);}}
    public CompletionStage<Void> ready(){return initial;}
    public Skill skill(String id){return api.getGlobalRegistry().getSkill(NamespacedId.fromString(id));}
    public Stat stat(String id){var stat=api.getGlobalRegistry().getStat(NamespacedId.fromString(id));if(stat==null||!stat.isEnabled())throw new IllegalArgumentException("RPG_STAT_"+id);return stat;}
    public boolean valid(){try{for(var g:gear)if(!stat(g.stat()).isEnabled())return false;for(var c:custom.values())if(!c.skill().isEnabled()||!c.active().isEnabled()||!stat(c.stat()).isEnabled())return false;return true;}catch(RuntimeException missing){return false;}}
    public boolean loaded(UUID player){return valid()&&api.getUser(player).isLoaded();}
    public boolean penalized(UUID player){if(!policy.penaltyEnabled())return false;var user=api.getUser(player);if(!user.isLoaded())return true;var values=new HashMap<String,Integer>();for(String id:policy.penaltyRule().skills()){var skill=skill(id);if(skill==null)return true;values.put(id,user.getSkillLevel(skill));}return policy.penaltyRule().allows(new WorldAccessPolicy.Levels(true,values));}
    public double itemRate(ItemStack item,double fallback){if(fallback==0)return 0;var meta=item.getItemMeta();Double matched=null;if(meta!=null)for(var key:meta.getPersistentDataContainer().getKeys()){Double value=policy.itemRates().get("pdc/"+key);if(value!=null){if(matched!=null&&!matched.equals(value))throw new IllegalStateException("RPG_ITEM_RATE_AMBIGUOUS");matched=value;}}return matched!=null?matched:policy.itemRates().getOrDefault(item.getType().getKey().toString(),fallback);}
    public Map<String,Double> gearValues(ItemStack[] items){var values=new HashMap<String,Double>();for(int slot=0;slot<items.length;slot++){var item=items[slot];if(item==null||item.isEmpty()||!item.hasItemMeta())continue;var pdc=item.getItemMeta().getPersistentDataContainer();int upgrade=io.github.jesterportfolio.hearth.survival.platform.EquipmentData.level(item);if(upgrade<0||upgrade>1000)throw new IllegalStateException("RPG_UPGRADE_DATA");for(var g:gear){if(!g.slots().contains(slot)||!g.materials().contains(item.getType().getKey().toString()))continue;var key=Objects.requireNonNull(NamespacedKey.fromString(g.enchant()));int enchant=pdc.getOrDefault(key,PersistentDataType.INTEGER,0);if(enchant<0||enchant>1000)throw new IllegalStateException("RPG_ENCHANT_DATA");double amount=Math.clamp(upgrade*g.upgrade()+enchant*g.enchantValue(),-g.cap(),g.cap());if(amount!=0)values.put("hearth:gear/"+slot+"/"+g.id(),amount);}}return Map.copyOf(values);}
    public void reconcile(Player player,boolean allowed){var user=api.getUser(player.getUniqueId());if(!user.isLoaded())return;var next=new HashMap<String,Double>();if(allowed){next.putAll(gearValues(new ItemStack[]{player.getInventory().getItemInMainHand(),player.getInventory().getItemInOffHand(),player.getInventory().getHelmet(),player.getInventory().getChestplate(),player.getInventory().getLeggings(),player.getInventory().getBoots()}));
            for(var entry:custom.entrySet()){var c=entry.getValue();int level=user.getAbilityLevel(c.passive());if(level>0)next.put("hearth:passive/"+entry.getKey(),c.passive().getValue(level));}}
        var contributions=new TreeMap<String,io.github.jesterportfolio.hearth.survival.platform.StatLedger.Contribution>();
        for(var entry:next.entrySet()){String name=entry.getKey(),id=name.substring(name.lastIndexOf('/')+1);String statId=name.startsWith("hearth:gear/")?gear.stream().filter(g->g.id().equals(id)).findFirst().orElseThrow().stat():custom.get(id).stat();contributions.put(name,new io.github.jesterportfolio.hearth.survival.platform.StatLedger.Contribution(statId,entry.getValue()));}
        replaceSources(player.getUniqueId(),"equipment",contributions);if(!allowed){replaceSources(player.getUniqueId(),"enchants",Map.of());sources.remove(player.getUniqueId());}applied.put(player.getUniqueId(),Map.copyOf(next));
    }

    private void writeConfig(Path file,org.bukkit.configuration.file.YamlConfiguration yaml)throws Exception{Path backup=file.resolveSibling(file.getFileName()+".hearth-before");if(!Files.exists(backup,LinkOption.NOFOLLOW_LINKS))Files.copy(file,backup,StandardCopyOption.COPY_ATTRIBUTES);else if(!backup.equals(backup.toRealPath()))throw new IllegalStateException("AURA_CONFIG_BACKUP_PATH");Path temp=file.resolveSibling(file.getFileName()+".hearth-writing");Files.createFile(temp,java.nio.file.attribute.PosixFilePermissions.asFileAttribute(Files.getPosixFilePermissions(file)));try(var writer=Files.newBufferedWriter(temp,StandardOpenOption.WRITE)){writer.write(yaml.saveToString());}try(var channel=FileChannel.open(temp,StandardOpenOption.WRITE)){channel.force(true);}Files.move(temp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
    public CompletionStage<Void> project(Set<String> blocked,Set<String> disabled){try{
        if(!Bukkit.isPrimaryThread())throw new IllegalStateException("AURA_PROJECTION_MAIN_THREAD");var aura=Objects.requireNonNull(Bukkit.getPluginManager().getPlugin("AuraSkills"));Path data=aura.getDataFolder().toPath().toAbsolutePath();Path marker=plugin.getDataFolder().toPath().toAbsolutePath().resolve("rpg-aura-projection.pending");if(Files.exists(marker,LinkOption.NOFOLLOW_LINKS))throw new IllegalStateException("AURA_PROJECTION_HOLD");
        Path file=data.resolve("config.yml"),manaFile=data.resolve("mana_abilities.yml");for(var f:List.of(file,manaFile))if(!f.equals(f.toRealPath())||Files.size(f)>2_000_000)throw new IllegalStateException("AURA_CONFIG_PATH");
        var yaml=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(file.toFile());var mana=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(manaFile.toFile());Path ownedFile=plugin.getDataFolder().toPath().toAbsolutePath().resolve("rpg-aura-worlds.properties");var owned=new Properties();if(Files.exists(ownedFile)){if(!ownedFile.equals(ownedFile.toRealPath())||Files.size(ownedFile)>1_000_000)throw new IllegalStateException("AURA_WORLD_LEDGER");try(var reader=Files.newBufferedReader(ownedFile)){owned.load(reader);}}
        var nextOwned=new Properties();boolean changed=false;
        for(var row:Map.of("blocked_worlds",blocked,"disabled_worlds",disabled).entrySet()){var original=new TreeSet<>(yaml.getStringList(row.getKey()));var oldOwned=new HashSet<>(Arrays.asList(owned.getProperty(row.getKey(),"").split(",")));var foreign=new TreeSet<>(original);foreign.removeAll(oldOwned);var names=new TreeSet<>(foreign);names.addAll(row.getValue());var ours=new TreeSet<>(row.getValue());ours.removeAll(foreign);nextOwned.setProperty(row.getKey(),String.join(",",ours));if(!names.equals(original)){yaml.set(row.getKey(),new ArrayList<>(names));changed=true;}}
        for(String key:List.of("action_bar.enabled","boss_bar.enabled","on_death.reset_skills","on_death.reset_xp"))if(yaml.getBoolean(key)){yaml.set(key,false);changed=true;}
        boolean manaChanged=false;for(String key:List.of("mana_abilities.auraskills/treecapitator.call_block_break_event","mana_abilities.auraskills/treecapitator.call_block_drop_item_event","mana_abilities.auraskills/terraform.call_block_drop_item_event"))if(!mana.getBoolean(key)){mana.set(key,true);manaChanged=true;}
        if(!changed&&!manaChanged)return CompletableFuture.completedFuture(null);
        var lease=io.github.jesterportfolio.hearth.administration.RuntimeLease.acquire(marker,"Hearth Aura config projection v1\n").orElseThrow();if(changed)writeConfig(file,yaml);if(manaChanged)writeConfig(manaFile,mana);
        if(!Bukkit.dispatchCommand(Bukkit.getConsoleSender(),"auraskills:skills reload"))throw new IllegalStateException("AURA_RELOAD_COMMAND");validateContent();
        Path next=ownedFile.resolveSibling(ownedFile.getFileName()+".writing");try(var writer=Files.newBufferedWriter(next,StandardOpenOption.CREATE_NEW)){nextOwned.store(writer,"Hearth-owned Aura world lists; external names preserved");}try(var channel=FileChannel.open(next,StandardOpenOption.WRITE)){channel.force(true);}Files.move(next,ownedFile,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);lease.clean();return CompletableFuture.completedFuture(null);
    }catch(Exception error){return CompletableFuture.failedFuture(error);}}
    public void close(){closed=true;HandlerList.unregisterAll(this);for(var p:Bukkit.getOnlinePlayers())clearSources(p.getUniqueId());sources.clear();rendered.clear();applied.clear();}
}
